//! gamescope action bindings: private keyboard-hotkey protocol.
//!
//! Steam registers keyboard chords (`GuideKeyboardHotkey`, `QAMKeyboardHotkey`)
//! on the gamescope-only `gamescope_action_binding_manager` Wayland global, and
//! expects a `gamescope_action_binding.triggered` event when the chord is held
//! so it can open its overlay. The compositor owns the held-key state and matches
//! it against the armed bindings; the client never sees the raw chord as a
//! hotkey.
//!
//! This module owns both halves: the vendored protocol bindings (generated by
//! `wayland-scanner` at compile time from
//! `protocol/gamescope-action-binding.xml`) and the hotkey state machine
//! (`Registry` / `Binding` / `Trigger`). `shell` feeds every key event through
//! [`ActionBindings::on_key`] from inside the Smithay keyboard input filter and
//! intercepts the chord when a binding asks for it.
//!
//! The behaviour mirrors gamescope's `CGamescopeActionBinding` and
//! `wlserver_process_hotkeys` (`src/WaylandServer/GamescopeActionBinding.h`,
//! `src/wlserver.cpp:2556`).

use std::collections::{BTreeMap, BTreeSet};

use smithay::{
	input::keyboard::{
		Keysym, keysyms,
		xkb::{keysym_get_name, keysym_to_utf32, utf32_to_keysym},
	},
	reexports::rustix::time::{ClockId, clock_gettime},
	wayland::{Dispatch2, GlobalDispatch2},
};
use wayland_server::{
	Client, DataInit, DisplayHandle, New, Resource, WEnum,
	backend::{ClientId, GlobalId, ObjectId},
};

use crate::shell::FerriscopeState;

/// Server bindings for the vendored `gamescope_action_binding` protocol.
///
/// Generated at compile time by the `wayland-scanner` proc macros. The 0.31
/// line exposes code generation only as proc macros, so this is a normal
/// dependency rather than a `build.rs`/`OUT_DIR` step.
pub mod protocol {
	#![allow(
		dead_code,
		non_camel_case_types,
		unused_unsafe,
		unused_variables,
		non_upper_case_globals,
		non_snake_case,
		unused_imports,
		missing_docs
	)]
	#![allow(clippy::all)]

	/// Server-side API of the protocol.
	pub mod server {
		use wayland_server;
		use wayland_server::protocol::*;

		pub mod __interfaces {
			use wayland_server::protocol::__interfaces::*;
			wayland_scanner::generate_interfaces!("protocol/gamescope-action-binding.xml");
		}
		use self::__interfaces::*;

		wayland_scanner::generate_server_code!("protocol/gamescope-action-binding.xml");
	}
}

use protocol::server::gamescope_action_binding::{self, GamescopeActionBinding, TriggerFlag};
use protocol::server::gamescope_action_binding_manager::{self, GamescopeActionBindingManager};

/// A `arm_flag.one_shot` binding disarms itself after it triggers.
pub const ARM_FLAG_ONE_SHOT: u32 = 0x1;
/// The `arm_flag.no_block` bit (see [`blocks_input`] for the inverted gamescope
/// behaviour).
pub const ARM_FLAG_NO_BLOCK: u32 = 0x2;

/// Keysym remappings applied after uppercasing, copied from gamescope's
/// `k_mapKeysymRemapping` (`GamescopeActionBinding.h:53-67`): the X keymap may
/// deliver either aliased form depending on when the keyboard came online.
const KEYSYM_REMAP: &[(u32, u32)] = &[
	(keysyms::KEY_ISO_Left_Tab, keysyms::KEY_Tab),
	(keysyms::KEY_ISO_Enter, keysyms::KEY_Return),
	(keysyms::KEY_Meta_L, keysyms::KEY_Super_L),
	(keysyms::KEY_Meta_R, keysyms::KEY_Super_R),
	(keysyms::KEY_ISO_Level3_Shift, keysyms::KEY_Alt_R),
];

/// Whether a matching binding with these arm flags swallows the chord.
///
/// gamescope computes `bBlockInput = !!(arm_flags & NO_BLOCK)` and returns it
/// as "block" (`GamescopeActionBinding.h:165`, `:184`), i.e. it blocks when
/// `no_block` is set and forwards when it is clear — the **inverse** of the
/// protocol's documented `no_block` ("don't block ... and keep processing
/// hotkeys"). ferriscope reproduces the observed gamescope behaviour so Steam's
/// registered hotkeys behave exactly as they do on gamescope; the documented
/// intent would be `arm_flags & !NO_BLOCK`.
pub const fn blocks_input(arm_flags: u32) -> bool {
	arm_flags & ARM_FLAG_NO_BLOCK != 0
}

/// Uppercase a keysym the way `xkb_keysym_to_upper` does, via its Unicode
/// mapping, then apply the alias remapping.
pub fn normalize_keysym(raw: u32) -> u32 {
	let mut sym = keysym_to_upper(Keysym::new(raw)).raw();
	for (bad, good) in KEYSYM_REMAP {
		if sym == *bad {
			sym = *good;
		}
	}
	sym
}

/// Simple single-character uppercase; a mapping that expands to several
/// characters (or to nothing) leaves the keysym unchanged, matching
/// `xkb_keysym_to_upper`'s single-character contract.
fn keysym_to_upper(keysym: Keysym) -> Keysym {
	let codepoint = keysym_to_utf32(keysym);
	if codepoint == 0 {
		return keysym;
	}
	let Some(ch) = char::from_u32(codepoint) else {
		return keysym;
	};
	let mut upper = ch.to_uppercase();
	match (upper.next(), upper.next()) {
		(Some(up), None) if up != ch => utf32_to_keysym(up as u32),
		_ => keysym,
	}
}

/// One normalized keyboard trigger: the exact set of keysyms that must be held.
#[derive(Clone, Debug, PartialEq, Eq, Default)]
pub struct Trigger(BTreeSet<u32>);

impl Trigger {
	/// Build a trigger from raw keysyms, normalizing each one.
	pub fn from_keysyms<I: IntoIterator<Item = u32>>(keysyms: I) -> Self {
		Self(keysyms.into_iter().map(normalize_keysym).collect())
	}

	/// Build a trigger from the byte array `add_keyboard_trigger` carries.
	pub fn from_wire(keysyms: &[u8]) -> Self {
		Self::from_keysyms(
			keysyms
				.chunks_exact(4)
				.map(|chunk| u32::from_ne_bytes([chunk[0], chunk[1], chunk[2], chunk[3]])),
		)
	}

	/// Whether this trigger is exactly the held set.
	pub fn matches(&self, held: &BTreeSet<u32>) -> bool {
		&self.0 == held
	}

	/// Human-readable normalized names (`Tab + Shift_L`), like gamescope's
	/// `ComputeDebugName`.
	pub fn debug_name(&self) -> String {
		self.0
			.iter()
			.map(|sym| keysym_get_name(Keysym::new(*sym)))
			.collect::<Vec<_>>()
			.join(" + ")
	}
}

/// The mutable state of one `gamescope_action_binding` object.
#[derive(Clone, Debug, Default)]
pub struct Binding {
	description: String,
	triggers: Vec<Trigger>,
	arm_flags: Option<u32>,
}

impl Binding {
	/// Replace the human-readable description (debug only).
	pub fn set_description(&mut self, description: String) {
		self.description = description;
	}

	/// The description, for logging.
	pub fn description(&self) -> &str {
		&self.description
	}

	/// Add one keyboard trigger (gamescope appends; it never replaces).
	pub fn add_trigger(&mut self, trigger: Trigger) {
		self.triggers.push(trigger);
	}

	/// Drop every trigger.
	pub fn clear_triggers(&mut self) {
		self.triggers.clear();
	}

	/// Arm with these raw arm flags.
	pub fn arm(&mut self, arm_flags: u32) {
		self.arm_flags = Some(arm_flags);
	}

	/// Disarm.
	pub fn disarm(&mut self) {
		self.arm_flags = None;
	}

	/// Whether the binding is currently armed.
	pub fn is_armed(&self) -> bool {
		self.arm_flags.is_some()
	}
}

/// A `triggered` event the caller must send to the binding at index `binding`,
/// carrying the allocated global `sequence` number.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Emission {
	/// Index into the binding list.
	pub binding: usize,
	/// The global sequence number, shared across all bindings.
	pub sequence: u32,
}

/// The pure hotkey state machine: bindings, the held-keysym set and the
/// trigger sequence. Holds no Wayland resources, so it is unit-testable.
#[derive(Debug, Default)]
pub struct Registry {
	bindings: Vec<Binding>,
	pressed: BTreeMap<u32, u32>,
	sequence: u32,
}

impl Registry {
	/// Register a new binding and return its index.
	pub fn push(&mut self) -> usize {
		self.bindings.push(Binding::default());
		self.bindings.len() - 1
	}

	/// Remove a binding, keeping the remaining indices stable.
	pub fn remove(&mut self, index: usize) -> Option<Binding> {
		(index < self.bindings.len()).then(|| self.bindings.remove(index))
	}

	/// The binding at `index`, mutably.
	pub fn binding_mut(&mut self, index: usize) -> Option<&mut Binding> {
		self.bindings.get_mut(index)
	}

	/// A consistent snapshot of the held set, for debugging.
	pub fn pressed_keysyms(&self) -> BTreeSet<u32> {
		self.pressed.values().copied().collect()
	}

	/// Feed one key event and return the bindings to notify plus whether the
	/// event must be swallowed.
	///
	/// Mirrors `wlserver_process_hotkeys` (`wlserver.cpp:2556-2619`): the held
	/// set is derived from normalized keysyms; a release that leaves an aliased
	/// keysym still held does not re-run matching (so releasing one of two
	/// keycodes mapping to the same keysym cannot re-trigger); matching is
	/// in binding registration order, and the first blocking match stops
	/// processing.
	pub fn on_key(&mut self, keycode: u32, keysym: u32, pressed: bool) -> (Vec<Emission>, bool) {
		if pressed {
			self.pressed.insert(keycode, normalize_keysym(keysym));
		} else {
			let Some(released) = self.pressed.get(&keycode).copied() else {
				// A release we never saw the press for cannot end a binding.
				return (Vec::new(), false);
			};
			self.pressed.remove(&keycode);
			if self.pressed.values().any(|held| *held == released) {
				// Another keycode still holds this keysym: not a transition.
				return (Vec::new(), false);
			}
		}

		let held = self.pressed_keysyms();
		let mut emissions = Vec::new();
		for (index, binding) in self.bindings.iter_mut().enumerate() {
			if !binding.is_armed() {
				continue;
			}
			for trigger in &binding.triggers {
				let Some(arm_flags) = binding.arm_flags else {
					break;
				};
				if !trigger.matches(&held) {
					continue;
				}
				let sequence = self.sequence;
				self.sequence = self.sequence.wrapping_add(1);
				emissions.push(Emission {
					binding: index,
					sequence,
				});
				if arm_flags & ARM_FLAG_ONE_SHOT != 0 {
					binding.arm_flags = None;
				}
				if blocks_input(arm_flags) {
					return (emissions, true);
				}
			}
		}
		(emissions, false)
	}
}

/// The `gamescope_action_binding_manager` global plus every live binding.
///
/// The registry and the Wayland resource handles are kept index-aligned; the
/// resource list is only touched by the dispatch handlers below.
#[derive(Default)]
pub struct ActionBindings {
	registry: Registry,
	objects: Vec<GamescopeActionBinding>,
}

impl ActionBindings {
	/// An empty set of bindings.
	pub fn new() -> Self {
		Self::default()
	}

	/// The global created in `shell`, kept so it lives as long as the state.
	pub fn global(display: &DisplayHandle) -> GlobalId {
		display.create_global::<FerriscopeState, GamescopeActionBindingManager, ActionBindingManagerData>(
			1,
			ActionBindingManagerData,
		)
	}

	/// Track a newly created binding object.
	pub fn create(&mut self, object: GamescopeActionBinding) {
		tracing::info!(id = ?object.id(), "action binding created");
		self.registry.push();
		self.objects.push(object);
	}

	/// Drop a binding object's state; called from the dispatch `destroyed`.
	pub fn remove(&mut self, id: ObjectId) {
		if let Some(index) = self.objects.iter().position(|object| object.id() == id) {
			self.objects.remove(index);
			self.registry.remove(index);
		}
	}

	fn state_mut(&mut self, resource: &GamescopeActionBinding) -> Option<&mut Binding> {
		let index = self.objects.iter().position(|object| object.id() == resource.id())?;
		self.registry.binding_mut(index)
	}

	/// `set_description`.
	pub fn set_description(&mut self, resource: &GamescopeActionBinding, description: String) {
		tracing::info!(id = ?resource.id(), description = %description, "action binding described");
		if let Some(binding) = self.state_mut(resource) {
			binding.set_description(description);
		}
	}

	/// `add_keyboard_trigger`; the wire array is raw `xkb_keysym_t`s.
	pub fn add_keyboard_trigger(&mut self, resource: &GamescopeActionBinding, keysyms: &[u8]) {
		let trigger = Trigger::from_wire(keysyms);
		if let Some(binding) = self.state_mut(resource) {
			tracing::info!(
				id = ?resource.id(),
				description = binding.description(),
				trigger = trigger.debug_name(),
				"action binding: adding trigger",
			);
			binding.add_trigger(trigger);
		}
	}

	/// `clear_triggers`.
	pub fn clear_triggers(&mut self, resource: &GamescopeActionBinding) {
		if let Some(binding) = self.state_mut(resource) {
			binding.clear_triggers();
		}
	}

	/// `arm`.
	pub fn arm(&mut self, resource: &GamescopeActionBinding, arm_flags: u32) {
		if let Some(binding) = self.state_mut(resource) {
			tracing::info!(
				id = ?resource.id(),
				description = binding.description(),
				arm_flags = format!("0x{arm_flags:x}"),
				"action binding armed",
			);
			binding.arm(arm_flags);
		}
	}

	/// `disarm`.
	pub fn disarm(&mut self, resource: &GamescopeActionBinding) {
		if let Some(binding) = self.state_mut(resource) {
			tracing::debug!(id = ?resource.id(), "action binding disarmed");
			binding.disarm();
		}
	}

	/// Feed a key event, emit `triggered` for every match and return whether the
	/// key must be swallowed.
	///
	/// The held set is tracked even while no client has registered a binding
	/// (gamescope updates its pressed map on every key), so a binding created
	/// mid-chord still sees the correct state.
	pub fn on_key(&mut self, keycode: u32, keysym: Keysym, pressed: bool) -> bool {
		let (emissions, block) = self.registry.on_key(keycode, keysym.raw(), pressed);
		if !emissions.is_empty() {
			let now = monotonic_nanos();
			let time_lo = now as u32;
			let time_hi = (now >> 32) as u32;
			for emission in emissions {
				if let Some(object) = self.objects.get(emission.binding) {
					tracing::debug!(
						id = ?object.id(),
						sequence = emission.sequence,
						"action binding triggered",
					);
					object.triggered(emission.sequence, time_lo, time_hi, TriggerFlag::Keyboard);
				}
			}
		}
		block
	}
}

/// Nanoseconds on `CLOCK_MONOTONIC`, matching gamescope's `get_time_in_nanos`.
fn monotonic_nanos() -> u64 {
	let timespec = clock_gettime(ClockId::Monotonic);
	(timespec.tv_sec as u64)
		.saturating_mul(1_000_000_000)
		.saturating_add(timespec.tv_nsec as u64)
}

/// User data for the `gamescope_action_binding_manager` global and its object.
pub struct ActionBindingManagerData;

/// User data for each `gamescope_action_binding` object.
pub struct ActionBindingData;

impl GlobalDispatch2<GamescopeActionBindingManager, FerriscopeState> for ActionBindingManagerData {
	fn bind(
		&self,
		_state: &mut FerriscopeState,
		_handle: &DisplayHandle,
		_client: &Client,
		resource: New<GamescopeActionBindingManager>,
		data_init: &mut DataInit<'_, FerriscopeState>,
	) {
		data_init.init(resource, ActionBindingManagerData);
	}
}

impl Dispatch2<GamescopeActionBindingManager, FerriscopeState> for ActionBindingManagerData {
	fn request(
		&self,
		state: &mut FerriscopeState,
		_client: &Client,
		_resource: &GamescopeActionBindingManager,
		request: gamescope_action_binding_manager::Request,
		_handle: &DisplayHandle,
		data_init: &mut DataInit<'_, FerriscopeState>,
	) {
		match request {
			gamescope_action_binding_manager::Request::Destroy => {},
			gamescope_action_binding_manager::Request::CreateActionBinding { callback } => {
				let object = data_init.init(callback, ActionBindingData);
				state.action_bindings.create(object);
			},
		}
	}
}

impl Dispatch2<GamescopeActionBinding, FerriscopeState> for ActionBindingData {
	fn request(
		&self,
		state: &mut FerriscopeState,
		_client: &Client,
		resource: &GamescopeActionBinding,
		request: gamescope_action_binding::Request,
		_handle: &DisplayHandle,
		_data_init: &mut DataInit<'_, FerriscopeState>,
	) {
		use gamescope_action_binding::Request;
		match request {
			Request::Destroy => {},
			Request::SetDescription { description } => state.action_bindings.set_description(resource, description),
			Request::AddKeyboardTrigger { keysyms } => state.action_bindings.add_keyboard_trigger(resource, &keysyms),
			Request::ClearTriggers => state.action_bindings.clear_triggers(resource),
			Request::Arm { arm_flags } => {
				let flags = match arm_flags {
					WEnum::Value(flags) => flags.bits(),
					WEnum::Unknown(flags) => flags,
				};
				state.action_bindings.arm(resource, flags);
			},
			Request::Disarm => state.action_bindings.disarm(resource),
		}
	}

	fn destroyed(&self, state: &mut FerriscopeState, _client: ClientId, resource: &GamescopeActionBinding) {
		state.action_bindings.remove(resource.id());
	}
}

#[cfg(test)]
mod tests {
	use super::*;
	use smithay::input::keyboard::keysyms::{
		KEY_Alt_R, KEY_Control_L, KEY_ISO_Left_Tab, KEY_ISO_Level3_Shift, KEY_Meta_L, KEY_Shift_L, KEY_Super_L,
		KEY_Tab, KEY_p,
	};

	/// The evdev codes used by the control stream, for readable tests.
	const SHIFT: u32 = 42;
	const TAB: u32 = 15;
	const CTRL: u32 = 29;

	fn trigger(keys: &[u32]) -> Trigger {
		Trigger::from_keysyms(keys.iter().copied())
	}

	#[test]
	fn normalization_uppercases_letters() {
		assert_eq!(normalize_keysym(KEY_p), keysyms::KEY_P);
		assert_eq!(normalize_keysym(keysyms::KEY_P), keysyms::KEY_P);
	}

	#[test]
	fn normalization_remaps_aliases() {
		assert_eq!(normalize_keysym(KEY_ISO_Left_Tab), KEY_Tab);
		assert_eq!(normalize_keysym(KEY_Meta_L), KEY_Super_L);
		assert_eq!(normalize_keysym(KEY_ISO_Level3_Shift), KEY_Alt_R);
		// A non-aliased modifier is untouched.
		assert_eq!(normalize_keysym(KEY_Shift_L), KEY_Shift_L);
	}

	#[test]
	fn trigger_from_wire_reads_native_u32s() {
		let mut bytes = Vec::new();
		for keysym in [KEY_Shift_L, KEY_Tab] {
			bytes.extend_from_slice(&keysym.to_ne_bytes());
		}
		let from_wire = Trigger::from_wire(&bytes);
		assert_eq!(from_wire, trigger(&[KEY_Shift_L, KEY_Tab]));
	}

	#[test]
	fn shift_tab_matches_despite_iso_left_tab() {
		let mut registry = Registry::default();
		let index = registry.push();
		registry
			.binding_mut(index)
			.unwrap()
			.add_trigger(trigger(&[KEY_Tab, KEY_Shift_L]));
		registry.binding_mut(index).unwrap().arm(0);

		assert_eq!(registry.on_key(SHIFT, KEY_Shift_L, true), (Vec::new(), false));
		// X delivers ISO_Left_Tab while Shift is held; normalization folds it to Tab.
		let (emissions, block) = registry.on_key(TAB, KEY_ISO_Left_Tab, true);
		assert_eq!(emissions.len(), 1);
		assert!(!block, "gamescope only blocks when no_block is set");
		assert_eq!(emissions[0].binding, index);
		assert_eq!(emissions[0].sequence, 0);
	}

	#[test]
	fn trigger_selection_is_registration_order() {
		let mut registry = Registry::default();
		let first = registry.push();
		registry
			.binding_mut(first)
			.unwrap()
			.add_trigger(trigger(&[KEY_Shift_L, KEY_Tab]));
		registry.binding_mut(first).unwrap().arm(0);
		let second = registry.push();
		registry
			.binding_mut(second)
			.unwrap()
			.add_trigger(trigger(&[KEY_Shift_L, KEY_Tab]));
		registry.binding_mut(second).unwrap().arm(0);

		registry.on_key(SHIFT, KEY_Shift_L, true);
		let (emissions, _) = registry.on_key(TAB, KEY_Tab, true);
		assert_eq!(emissions.len(), 2, "both armed bindings match");
		assert_eq!(emissions[0].binding, first);
		assert_eq!(emissions[1].binding, second);
		assert!(registry.binding_mut(first).unwrap().is_armed());
		assert!(registry.binding_mut(second).unwrap().is_armed());
	}

	#[test]
	fn one_shot_disarms() {
		let mut registry = Registry::default();
		let index = registry.push();
		registry
			.binding_mut(index)
			.unwrap()
			.add_trigger(trigger(&[KEY_Shift_L, KEY_Tab]));
		registry.binding_mut(index).unwrap().arm(ARM_FLAG_ONE_SHOT);

		registry.on_key(SHIFT, KEY_Shift_L, true);
		let (emissions, _) = registry.on_key(TAB, KEY_Tab, true);
		assert_eq!(emissions.len(), 1);
		assert!(!registry.binding_mut(index).unwrap().is_armed());

		// Release and press again: no further trigger.
		registry.on_key(TAB, KEY_Tab, false);
		registry.on_key(SHIFT, KEY_Shift_L, false);
		registry.on_key(SHIFT, KEY_Shift_L, true);
		let (emissions, _) = registry.on_key(TAB, KEY_Tab, true);
		assert!(emissions.is_empty());
	}

	#[test]
	fn disarm_stops_matching_and_arm_rearms() {
		let mut registry = Registry::default();
		let index = registry.push();
		registry
			.binding_mut(index)
			.unwrap()
			.add_trigger(trigger(&[KEY_Shift_L, KEY_Tab]));
		fn press(registry: &mut Registry) -> Vec<Emission> {
			registry.on_key(SHIFT, KEY_Shift_L, true);
			let (emissions, _) = registry.on_key(TAB, KEY_Tab, true);
			registry.on_key(TAB, KEY_Tab, false);
			registry.on_key(SHIFT, KEY_Shift_L, false);
			emissions
		}

		registry.binding_mut(index).unwrap().disarm();
		assert!(press(&mut registry).is_empty());

		registry.binding_mut(index).unwrap().arm(0);
		assert_eq!(press(&mut registry).len(), 1);
	}

	#[test]
	fn no_block_blocks_in_gamescope() {
		let mut registry = Registry::default();
		let index = registry.push();
		registry
			.binding_mut(index)
			.unwrap()
			.add_trigger(trigger(&[KEY_Shift_L, KEY_Tab]));
		registry.binding_mut(index).unwrap().arm(ARM_FLAG_NO_BLOCK);

		registry.on_key(SHIFT, KEY_Shift_L, true);
		let (emissions, block) = registry.on_key(TAB, KEY_Tab, true);
		assert_eq!(emissions.len(), 1);
		assert!(block, "gamescope returns the inverted no_block as block");
	}

	#[test]
	fn releasing_one_alias_does_not_re_trigger() {
		// Two keycodes resolving to the same keysym: releasing one must not
		// restart matching (gamescope's release guard).
		let mut registry = Registry::default();
		let index = registry.push();
		registry
			.binding_mut(index)
			.unwrap()
			.add_trigger(trigger(&[KEY_Shift_L, KEY_Tab]));
		registry.binding_mut(index).unwrap().arm(0);

		registry.on_key(SHIFT, KEY_Shift_L, true);
		registry.on_key(SHIFT + 100, KEY_Shift_L, true);
		let (emissions, _) = registry.on_key(TAB, KEY_Tab, true);
		assert_eq!(emissions.len(), 1);
		// Release the second Shift: Tab and Shift are still held, so no re-match.
		let (emissions, _) = registry.on_key(SHIFT + 100, KEY_Shift_L, false);
		assert!(emissions.is_empty());
	}

	#[test]
	fn sequence_increments_per_emission() {
		let mut registry = Registry::default();
		let index = registry.push();
		registry
			.binding_mut(index)
			.unwrap()
			.add_trigger(trigger(&[KEY_Shift_L, KEY_Tab]));
		registry.binding_mut(index).unwrap().arm(0);

		let chord = |registry: &mut Registry| {
			registry.on_key(SHIFT, KEY_Shift_L, true);
			let (emissions, _) = registry.on_key(TAB, KEY_Tab, true);
			registry.on_key(TAB, KEY_Tab, false);
			registry.on_key(SHIFT, KEY_Shift_L, false);
			emissions
		};

		let first = chord(&mut registry);
		assert_eq!(first.len(), 1);
		assert_eq!(first[0].sequence, 0);

		let second = chord(&mut registry);
		assert_eq!(second.len(), 1);
		assert_eq!(second[0].sequence, 1);
	}

	#[test]
	fn clear_triggers_and_multiple_triggers() {
		let mut registry = Registry::default();
		let index = registry.push();
		let binding = registry.binding_mut(index).unwrap();
		binding.add_trigger(trigger(&[KEY_Shift_L, KEY_Tab]));
		binding.add_trigger(trigger(&[KEY_Control_L, KEY_Shift_L, KEY_Tab]));
		binding.arm(0);
		assert_eq!(binding.triggers.len(), 2);

		registry.on_key(SHIFT, KEY_Shift_L, true);
		registry.on_key(CTRL, KEY_Control_L, true);
		let (emissions, _) = registry.on_key(TAB, KEY_Tab, true);
		assert_eq!(emissions.len(), 1, "only the Ctrl+Shift+Tab trigger matches");

		registry.binding_mut(index).unwrap().clear_triggers();
		assert!(registry.binding_mut(index).unwrap().triggers.is_empty());
	}

	#[test]
	fn blocks_input_is_gamescope_inverted() {
		assert!(blocks_input(ARM_FLAG_NO_BLOCK));
		assert!(!blocks_input(0));
		assert!(!blocks_input(ARM_FLAG_ONE_SHOT));
	}
}
